.action-example { padding: 11px 14px; border-left: 3px solid var(--orange); background: var(--lavender); font-size: 14px; line-height: 1.45; }
.plan-form { display: grid; gap: 7px; margin-top: 19px; }
.plan-form label, .copy-fallback label { color: var(--blue-dark); font-size: 14px; font-weight: 800; }
.optional { margin-left: 4px; color: var(--muted); font-size: 12px; font-weight: 500; }
.plan-form input, .copy-fallback textarea {
  width: 100%;
  min-height: 43px;
  margin-bottom: 6px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: #fff;
  font-size: 15px;
}
.plan-form input::placeholder { color: var(--muted); }
.panel-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-top: 10px; }
.plan-details { margin: 0 0 14px; padding: 0 14px; border-left: 3px solid var(--orange); background: var(--lavender); }
.plan-details div { padding: 9px 0; }
.plan-details div + div { border-top: 1px solid var(--line); }
.plan-details dt { color: var(--blue-dark); font-size: 12px; font-weight: 800; }
.plan-details dd { margin: 2px 0 0; overflow-wrap: anywhere; }
.session-note { margin-bottom: 15px; color: var(--muted); font-size: 14px; line-height: 1.45; }
.copy-fallback { margin-top: 16px; }
.copy-fallback textarea { display: block; margin-top: 5px; resize: vertical; }
.text-button {
  min-height: 40px;
  padding: 4px 6px;
  border: 0;
  color: var(--blue);
  background: transparent;
  font-size: 14px;
  font-weight: 780;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.text-button:hover { color: var(--blue-dark); }
.back-button { margin: -11px 0 8px -6px; }
.saved-list { display: grid; gap: 6px; margin: 0; padding: 0; list-style: none; }
.saved-list button {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: 4px;
  color: var(--blue);
  background: transparent;
  text-align: left;
}
.saved-list button:hover { border-color: var(--blue); background: var(--lavender); }
.saved-list strong, .saved-list span span { display: block; }
.saved-list span span { margin-top: 2px; color: var(--muted); font-size: 12px; }

